"use strict";
const categories={unclassified:"Not sorted yet",brick:"Brick walls",paper:"Paper walls",partition:"Partition walls",mindset:"Mindset issues"};
const key="breaking-shell-v1";
let state={version:1,stage:"collect",purpose:"",barriers:[]};
const status=document.getElementById("status");
try { const saved=JSON.parse(localStorage.getItem(key)||"null"); if(saved&&saved.version===1&&Array.isArray(saved.barriers)){state={version:1,stage:saved.stage==="sort"?"sort":"collect",purpose:String(saved.purpose||""),barriers:saved.barriers.filter(b=>b&&typeof b.text==="string").map(b=>({id:String(b.id),text:b.text,category:categories[b.category]?b.category:"unclassified",action:String(b.action||"")}))};} } catch {status.textContent="Saved work could not be loaded. You can start a new exercise.";}
function save(){try{localStorage.setItem(key,JSON.stringify(state));status.textContent="Saved in this browser.";}catch{status.textContent="This browser cannot save the exercise. Use Print / save PDF to keep your work.";}}
const purpose=document.getElementById("purpose");purpose.value=state.purpose;purpose.addEventListener("input",()=>{state.purpose=purpose.value;save();});
function removeButton(b){const button=document.createElement("button");button.type="button";button.className="secondary";button.textContent="Remove";button.setAttribute("aria-label","Remove barrier: "+b.text);button.onclick=()=>{state.barriers=state.barriers.filter(x=>x.id!==b.id);save();render();};return button;}
function render(){const sorting=state.stage==="sort";document.getElementById("sorting").hidden=!sorting;document.getElementById("action-guidance").hidden=!sorting;document.getElementById("long-list").hidden=sorting;document.getElementById("begin-sorting").hidden=sorting;document.getElementById("begin-sorting").disabled=!state.barriers.length;document.getElementById("stage-heading").textContent=sorting?"Add another barrier":"1. List the barriers";document.getElementById("collect-instructions").hidden=sorting;
const list=document.getElementById("barrier-list");list.replaceChildren();Object.keys(categories).forEach(c=>document.getElementById(c).replaceChildren());
state.barriers.forEach(b=>{const li=document.createElement("li");const text=document.createElement("span");text.textContent=b.text;li.append(text,removeButton(b));list.append(li);if(!sorting)return;
const card=document.createElement("article");card.className="card";const p=document.createElement("p");p.textContent=b.text;const label=document.createElement("label");label.textContent="Category";const select=document.createElement("select");Object.entries(categories).forEach(([value,name])=>{const option=document.createElement("option");option.value=value;option.textContent=name;select.append(option);});select.value=b.category;select.onchange=()=>{b.category=select.value;save();render();};label.append(select);const actionLabel=document.createElement("label");actionLabel.textContent="Next action, owner, and date";const action=document.createElement("textarea");action.value=b.action;action.oninput=()=>{b.action=action.value;save();};actionLabel.append(action);card.append(p,label,actionLabel,removeButton(b));document.getElementById(b.category).append(card);});document.getElementById("unclassified-section").hidden=!state.barriers.some(b=>b.category==="unclassified");}
document.getElementById("add").onsubmit=e=>{e.preventDefault();const input=document.getElementById("barrier");if(!input.value.trim())return;state.barriers.push({id:(globalThis.crypto?.randomUUID?.() || "barrier-"+Date.now().toString(36)+"-"+Math.random().toString(36).slice(2)),text:input.value.trim(),category:"unclassified",action:""});input.value="";save();render();input.focus();};
document.getElementById("begin-sorting").onclick=()=>{state.stage="sort";save();render();document.getElementById("sorting").scrollIntoView({block:"start"});};
document.getElementById("back-to-list").onclick=()=>{state.stage="collect";save();render();document.getElementById("barrier").focus();};
document.getElementById("print").onclick=()=>window.print();
document.getElementById("clear").onclick=()=>{if(!confirm("Clear the purpose and all barriers from this browser? Save a PDF first if you need a copy."))return;state={version:1,stage:"collect",purpose:"",barriers:[]};purpose.value="";save();render();};render();
